INSERT INTO fault_knowledge (category, keywords, cause, suggestion) VALUES
    ('电气故障', '跳闸,空开,短路,漏电,焦糊,烧焦,冒烟', '线路短路、端子过热碳化或负载过大', '立即断电挂牌，检查端子紧固与绝缘，红外测温定位发热点，更换损坏元件'),
    ('电气故障', '黑屏,不通电,无法启动,无显示,开不了机', '供电回路断开、保险熔断或电源模块损坏', '检查进线电压与保险，测量电源模块输出，排查急停回路'),
    ('电气故障', '加热圈,温度上不去,温度达不到,不升温', '加热圈烧断、热电偶损坏或温控器故障', '逐段测量加热圈电阻，校验热电偶，必要时更换温控模块'),
    ('电气故障', '电机过热,电机发烫,热继电器,电机烧', '电机过载、轴承缺油或缺相运行', '测量三相电流，检查轴承润滑与热继电器整定值'),
    ('电气故障', '光栅,安全门,急停,保护失灵', '安全回路信号线破损或传感器失效', '停机禁止生产，检查光栅对射与信号线，完成遮挡测试后方可恢复'),
    ('电气故障', '电瓶,电池,电量,充电', '蓄电池老化或单格电压偏低', '测量各单格电压，均衡充电或更换故障单格'),
    ('电气故障', '门机,门锁,关不严,电梯', '门机皮带松弛或门锁触点接触不良', '调整门机皮带张力，清洁并检测门锁触点'),
    ('机械故障', '异响,噪音,振动,抖动,振纹', '轴承磨损、部件松动或旋转件不平衡', '停机检查轴承间隙与紧固件，必要时更换轴承并做动平衡'),
    ('机械故障', '跑偏,皮带,链条,打滑', '张紧不当或托辊平行度偏差', '调整张紧装置与托辊平行度，更换磨损件'),
    ('机械故障', '卡滞,卡死,不顺,移动困难', '导轨/导柱润滑不足或异物卡阻', '清理异物，检查导轨润滑与拉伤情况'),
    ('液压故障', '漏油,渗油,油缸,保压,压力下降', '密封圈老化、油管接头松动', '定位漏点，更换密封件，保压测试确认'),
    ('液压故障', '油温高,油温过高,动作变慢,无力,起升', '液压油不足或污染、冷却器堵塞、泵磨损', '检查油位与油质，清洗滤网和冷却器，必要时更换液压油'),
    ('气动故障', '气压,压力上不去,漏气,供气不足', '进气阀膜片破损、管路泄漏', '检查进气阀与管路接头，查漏补漏'),
    ('气动故障', '气缸,电磁阀,夹爪,不动作', '电磁阀卡滞或内漏、气源压力不足', '检查电磁阀动作与线圈，确认气源三联件压力'),
    ('数控系统', '报警,伺服,回零,未就绪,ALM', '伺服驱动器供电/通讯异常或编码器故障', '读取报警号查手册，检查驱动器端子与编码器线缆'),
    ('数控系统', '尺寸,精度,定位,忽大忽小,间隙', '丝杠反向间隙变大或参数漂移', '激光干涉仪检测精度，调整反向间隙补偿参数'),
    ('润滑冷却', '冷却液,不出水,冷却泵,刀具发热', '冷却泵堵塞或叶轮损坏', '清理水箱与过滤网，检查冷却泵叶轮'),
    ('润滑冷却', '润滑报警,油位低,缺油,润滑', '润滑泵或油路堵塞、油位不足', '补加润滑油，清洗单向阀与分配器'),
    ('润滑冷却', '排气温度,温度过高,温度偏高,出水温度,过热停机,高温', '冷却器积尘、油滤堵塞或冷却水不足', '清洗冷却器，更换机油滤芯，检查冷却水流量');
